package ru.mtproxy.picker;
import java.util.*;
public final class ManualListsCheck {
 public static void main(String[] args){ManualEntry alive=new ManualEntry("a","ALPHA.example",443,"s",false),gone=new ManualEntry("b","beta.example",443,"s",true),unknown=new ManualEntry("c","gamma.example",80,"s",false);alive.ms=12;gone.ms=-1;unknown.ms=-2;if(!ManualLists.dead(gone)||ManualLists.dead(alive)||ManualLists.dead(unknown))throw new AssertionError("Only checked failures may be deleted");if(!ManualLists.matches(alive,"alpha",1)||ManualLists.matches(unknown,"",2)||!ManualLists.matches(unknown,"80",3)||!ManualLists.matches(gone,"WEB",2))throw new AssertionError("Filters and search");List<ManualEntry> input=Arrays.asList(unknown,gone,alive);if(ManualLists.sorted(input,0).get(0)!=alive||input.get(0)!=unknown||ManualLists.sorted(input,1).get(0)!=alive)throw new AssertionError("Sorting / original list");ArrayList<ManualEntry> remaining=new ArrayList<>(input);remaining.removeIf(ManualLists::dead);if(remaining.size()!=2||!remaining.contains(unknown)||!remaining.contains(alive))throw new AssertionError("Cleanup preserved untested");System.out.println("PASS: search, status filters, sorting, removal of checked dead only");}
}
